 if(!alertPopupOpen)for(const a of items)alertShown[a.key]=now+settings.repeatMinutes*60000;
 const box=$('alert-popup');box.innerHTML=`<div class="cardtop"><h2>${window.e99Icon?e99Icon('bell'):''}Atenção aos prazos</h2><button class="e99-x" onclick="closeAlertPopup(60)" aria-label="Fechar e adiar avisos por 1 hora">${window.e99Icon?e99Icon('close')||'✕':'✕'}</button></div><p class="small">${items.length===1?'1 pendência precisa':items.length+' pendências precisam'} de atenção.</p>${alertRows(items,3)}${items.length>3?`<p class="small">Mais ${items.length-3===1?'1 pendência':(items.length-3)+' pendências'} em Alertas.</p>`:''}<div class="toolbar"><button class="primary" onclick="closeAlertPopup(15);go('alerts')">Ver todas</button><button onclick="closeAlertPopup(15)">Adiar 15 min</button><button onclick="closeAlertPopup(60)">Adiar 1 hora</button></div><p class="small">Os alertas funcionam enquanto este site estiver aberto.</p>`;box.classList.remove('hidden');alertPopupOpen=true;
