function authCheckRecord(r){if(!r||r.format!=='estoque99-conta-v1'||(r.id!==undefined&&(typeof r.id!=='string'||!/^STK-[0-9A-HJKMNP-TV-Z]{12}$/.test(r.id)))||typeof r.login!=='string'||r.login.length>80||typeof r.salt!=='string'||typeof r.iv!=='string'||typeof r.cipher!=='string'||r.cipher.length>24000000||!Number.isSafeInteger(r.revision)||r.revision<1||authUn64(r.salt).length!==16||authUn64(r.iv).length!==12||(r.recovery!==undefined&&(!r.recovery||typeof r.recovery.salt!=='string'||typeof r.recovery.iv!=='string'||typeof r.recovery.cipher!=='string'))||(r.bio!==undefined&&(!r.bio||typeof r.bio.id!=='string'||r.bio.id.length>2000||typeof r.bio.salt!=='string'||typeof r.bio.iv!=='string'||typeof r.bio.cipher!=='string')))throw Error('Arquivo de conta inválido.');return r}
