function authPinOld(pw){return /^[0-9]{4,8}$/.test(String(pw==null?'':pw))}
function authPasswordStrong(pw){pw=String(pw==null?'':pw);return pw.length>=8&&pw.length<=128&&/\p{L}/u.test(pw)&&/[0-9]/.test(pw)}
/* só nos testes automáticos (localhost) dá para criar conta com a senha antiga de números */
function authWeakTestOK(){try{return (location.hostname==='localhost'||location.hostname==='127.0.0.1')&&localStorage.getItem('e99-test-weak-pw')==='1'}catch(e){return false}}
