function authSetMode(mode){if(authBusy)return;authMode=mode;authPending=null;authError='';renderAuth()}
function authPasswordField(name,label,autocomplete){return `<label>${label}<input type="password" name="${name}" required maxlength="128" autocapitalize="none" spellcheck="false" autocomplete="${autocomplete}"></label>`}
function renderAuth(){document.body.classList.add('locked');if(bioSupported()){const d=authMode==='recover'?authRecoverDraft.login:authLoginDraft;if(d&&(!bioPrep||bioPrep.login!==authLoginName(d)))bioPrepare(d)}const box=$('auth-screen');box.hidden=false;if(authRecoveryShow){box.innerHTML=authRecoveryScreenHTML();return}if(authMode==='recover'){box.innerHTML=authRecoverHTML();return}const setup=!!authPending,signup=authMode==='signup';box.innerHTML=`<div class="auth-card"><div class="brand"><div class="logo logo-img" aria-hidden="true"><img alt="" src="data:image/svg+xml;base64,"></div><div><strong>STOK</strong><small>LOJAS G · ESTOQUE 99</small></div></div><h1>${setup?'Defina sua nova senha':signup?'Primeiro acesso do dono':'Seu estoque começa aqui.'}</h1><p class="subtitle">${setup?'Antes de acessar, substitua a senha inicial por uma senha só sua.':signup?'Crie a conta principal da loja. As outras contas você cria depois, em Administração.':'Entre para acessar planos de ação, corredores e notas fiscais.'}</p><div class="auth-error" role="alert">${esc(authError)}</div>${!authAvailable()?'<p class="notice">Este navegador não oferece a criptografia necessária. Use um navegador com criptografia disponível, em um contexto seguro. Não é possível criar uma conta sem esse recurso.</p>':`<form id="auth-form" onsubmit="authSubmit(event)"><div class="fields">${setup?'':signup?'<label>Nome do estoque / unidade<input name="store" required maxlength="80" placeholder="Ex.: Estoque 42"></label><label>Login<input name="login" required minlength="3" maxlength="80" autocomplete="username" placeholder="Escolha um login"></label><label>Seu e-mail (obrigatório)<input name="email" type="email" required maxlength="120" autocomplete="email" inputmode="email" placeholder="voce@gmail.com" oninvalid="this.setCustomValidity(this.value?\'Digite um e-mail válido (ex.: voce@gmail.com).\':\'Informe seu e-mail. Toda conta do Stok precisa de um e-mail.\')" oninput="this.setCustomValidity(\'\')"></label><label class="chat-check"><input type="checkbox" name="pc"> Conta do PC do estoque (a nuvem usa um login interno)</label>':`<label>Login<input name="login" required maxlength="80" autocomplete="username" placeholder="Seu login" value="${esc(authLoginDraft)}" oninput="bioPrepare(this.value)"></label>`}${authPasswordField('password',setup?'Nova senha':'Senha',setup||signup?'new-password':'current-password')}${setup||signup?authPasswordField('confirmation','Confirme a senha','new-password')+'<p class="small">Senha: 8+ caracteres, com letras e números.</p>':''}<button class="primary" type="submit" ${authBusy?'disabled':''}>${authBusy?'Aguarde…':setup?'Salvar senha e entrar':signup?'Criar conta':'Entrar'}</button>${!setup&&!signup&&bioSupported()?`<button type="button" class="bio-login" ${authBusy?'disabled':''} onclick="authBioLogin()">Entrar com Face ID / digital</button>`:''}</div></form>`}<div class="auth-actions">${setup?'<button onclick="authSetMode(\'login\')">Cancelar</button>':`<button onclick="authSetMode('${signup?'login':'signup'}')">${signup?'Já tenho uma conta':'Criar conta de outro estoque'}</button><button onclick="document.getElementById('auth-import').click()">Importar conta protegida</button>${signup?'':'<button onclick="authSetMode(\'recover\')">Esqueci a senha</button>'}`}</div><p class="small auth-foot">Cada conta fica guardada neste navegador, protegida pela senha. O HTML não leva os cadastros junto. Para transferir uma conta, exporte uma cópia protegida em Minha conta e leve também a senha. Limpar os dados do navegador pode apagar as contas.</p></div>`;}
function authNewAccountId(){const bytes=crypto.getRandomValues(new Uint8Array(12));const alphabet='0123456789ABCDEFGHJKMNPQRSTVWXYZ';let s='STK-';for(const b of bytes)s+=alphabet[b%32];return s}
function authEnsureId(record){if(record&&typeof record.id==='string'&&/^STK-[0-9A-HJKMNP-TV-Z]{12}$/.test(record.id))return record;return Object.assign({},record,{id:authNewAccountId()})}
function authPersistId(storeKey,record){try{const raw=localStorage.getItem(storeKey);if(!raw)return;const stored=JSON.parse(raw);if(stored&&!stored.id&&record.id){stored.id=record.id;localStorage.setItem(storeKey,JSON.stringify(stored))}}catch(e){}}
async function authCreate(login,store,password,data,role,email){const storeKey=await authStorageKey(login);if(localStorage.getItem(storeKey))throw Error('Já existe uma conta com este login neste navegador.');const record={format:'estoque99-conta-v1',id:authNewAccountId(),login:authLoginName(login),salt:authB64(crypto.getRandomValues(new Uint8Array(16))),revision:1};const bits=await authKeyBits(password,record.salt),key=await authKeyFromBits(bits);const recoveryCode=authNewRecoveryCode();record.recovery=await authWrapRecovery(recoveryCode,bits,record.login);const payload={store,role,state:validate(data)};if(typeof email==='string'&&email)payload.email=email.trim().toLowerCase().slice(0,120);const encrypted=await authEncrypt(key,record,payload);return {key,record:encrypted,storeKey,payload,recoveryCode}}
function authSaveNewAccount(session){if(localStorage.getItem(session.storeKey))throw Error('Este login acabou de ser cadastrado. Entre com a senha da conta.');localStorage.setItem(session.storeKey,JSON.stringify(session.record))}
const AUTH_CODE_CHARS='0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function authNewRecoveryCode(){const bytes=crypto.getRandomValues(new Uint8Array(24));let s='';for(const b of bytes)s+=AUTH_CODE_CHARS[b%32];return s}
function authNormalizeCode(text){return String(text==null?'':text).toUpperCase().replace(/O/g,'0').replace(/[IL]/g,'1').replace(/[^0-9A-Z]/g,'')}
function authFormatCode(code){return String(code).match(/.{1,4}/g).join('-')}
