function authRecoveryAAD(login){return authBytes(authLoginName(login)+'|recuperacao')}
async function authWrapRecovery(code,bits,login){const salt=crypto.getRandomValues(new Uint8Array(16)),key=await authRecoveryKey(code,salt),iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:authRecoveryAAD(login)},key,bits);return {salt:authB64(salt),iv:authB64(iv),cipher:authB64(cipher)}}
