/* Face ID / digital: passkey do aparelho com a extensão PRF. O segredo PRF vira uma chave AES que embrulha os mesmos bits da senha. */
var bioCapable=null,bioPrep=null,bioSetup=null,authSavedCode='';
async function bioCheck(){if(bioCapable!==null)return bioCapable;let ok=!!(window.PublicKeyCredential&&window.isSecureContext&&navigator.credentials&&navigator.credentials.create&&authAvailable());
 if(ok&&typeof PublicKeyCredential.getClientCapabilities==='function'){try{const c=await PublicKeyCredential.getClientCapabilities();if(c&&c['extension:prf']===false)ok=false}catch(e){}}
 if(ok&&typeof PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable==='function'){try{ok=await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable()}catch(e){ok=false}}
 bioCapable=ok;return ok}
function bioSupported(){return bioCapable===true}
function bioAAD(login){return authBytes(authLoginName(login)+'|biometria')}
async function bioKey(prf,login){const base=await crypto.subtle.importKey('raw',prf,'HKDF',false,['deriveKey']);return crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-256',salt:authBytes('estoque99-bio-v1'),info:authBytes(authLoginName(login))},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function bioWrap(key,bits,login,id,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:bioAAD(login)},key,bits);return {id,salt,iv:authB64(iv),cipher:authB64(cipher)}}
function bioPrfOut(cred){const r=cred&&cred.getClientExtensionResults?cred.getClientExtensionResults():null;const out=r&&r.prf&&r.prf.results&&r.prf.results.first;return out?new Uint8Array(out):null}
async function bioGet(bio){let cred;try{cred=await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{type:'public-key',id:authUn64(bio.id)}],userVerification:'required',timeout:60000,extensions:{prf:{eval:{first:authUn64(bio.salt)}}}}})}catch(e){throw Error(e&&e.name==='NotAllowedError'?'Face ID / digital cancelado, ou este aparelho não reconhece o desbloqueio desta conta.':'Não foi possível usar o Face ID / digital neste aparelho.')}
 const out=bioPrfOut(cred);if(!out)throw Error('Este aparelho ou navegador não oferece desbloqueio por Face ID / digital.');return out}
async function bioUnwrap(record){const out=await bioGet(record.bio);const key=await bioKey(out,record.login);let bits;try{bits=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:authUn64(record.bio.iv),additionalData:bioAAD(record.login)},key,authUn64(record.bio.cipher)))}catch(e){throw Error('O Face ID / digital desta conta não confere. Entre com a senha.')}return {bits,key}}
async function bioPrepare(value){const login=authLoginName(value||'');if(!login){bioPrep=null;return}try{const storeKey=await authStorageKey(login);bioPrep={login,storeKey}}catch(e){bioPrep=null}}
async function bioFindRecord(value){const login=authLoginName(value||'');if(!login)throw Error('Digite o login.');const storeKey=bioPrep&&bioPrep.login===login?bioPrep.storeKey:await authStorageKey(login);const raw=localStorage.getItem(storeKey);if(!raw)throw Error('Login não encontrado neste aparelho.');if(authIsBlocked(storeKey))throw Error('Esta conta foi bloqueada pelo ADM neste navegador.');const record=authCheckRecord(JSON.parse(raw));if(!record.bio)throw Error('Esta conta não tem Face ID / digital ativado neste aparelho. Entre com a senha.');return {raw,storeKey,record}}
function bioFindRecordSync(value){const login=authLoginName(value||'');if(!login||!bioPrep||bioPrep.login!==login)return null;const raw=localStorage.getItem(bioPrep.storeKey);if(!raw||authIsBlocked(bioPrep.storeKey))return null;try{const record=authCheckRecord(JSON.parse(raw));return record.bio?{raw,storeKey:bioPrep.storeKey,record}:null}catch(e){return null}}
async function authBioLogin(){if(authBusy)return;const input=document.querySelector('#auth-form input[name=login]'),value=input?input.value:'';authLoginDraft=value;if(!authLoginName(value)){authError='Digite o login antes de usar o Face ID / digital.';renderAuth();return}
 authBusy=true;authError='';try{const found=bioFindRecordSync(value)||await bioFindRecord(value);const {bits}=await bioUnwrap(found.record);let opened;try{opened=await authOpenWithBits(found.record,bits)}catch(e){throw Error('Não foi possível abrir a conta pelo Face ID / digital. Entre com a senha.')}authEnter({key:opened.key,record:found.record,storeKey:found.storeKey,payload:opened.payload})}catch(e){authError=e.message||'Não foi possível usar o Face ID / digital.'}finally{authBusy=false;if(!authSession)renderAuth()}}
async function authBioRecover(){if(authBusy)return;const form=$('auth-form');if(!form)return;const v=readForm(form);authRecoverDraft={login:v.login||'',code:v.code||''};try{if(!authLoginName(v.login||''))throw Error('Digite o login.');authPasswordCheck(v.password||'',v.confirmation||'')}catch(e){authError=e.message;renderAuth();return}
 authBusy=true;authError='';try{const found=bioFindRecordSync(v.login)||await bioFindRecord(v.login);const {bits,key}=await bioUnwrap(found.record);let opened;try{opened=await authOpenWithBits(found.record,bits)}catch(e){throw Error('Não foi possível abrir a conta pelo Face ID / digital.')}const code=authNewRecoveryCode();await authResetWithBits(found.record,found.raw,found.storeKey,opened.payload,v.password,code,key);authShownCode=code;go('account');notify('Senha redefinida. Guarde o novo código de recuperação.')}catch(e){authError=e.message||'Não foi possível redefinir a senha.'}finally{authBusy=false;if(!authSession)renderAuth()}}
async function authResetWithBits(record,raw,storeKey,payload,password,code,bioK){const salt=authB64(crypto.getRandomValues(new Uint8Array(16)));const newBits=await authKeyBits(password,salt),newKey=await authKeyFromBits(newBits);const next0=Object.assign({},record,{salt,revision:record.revision+1,recovery:await authWrapRecovery(code,newBits,record.login),bio:bioK&&record.bio?await bioWrap(bioK,newBits,record.login,record.bio.id,record.bio.salt):undefined});const next=JSON.parse(JSON.stringify(await authEncrypt(newKey,next0,payload)));if(localStorage.getItem(storeKey)!==raw)throw Error('Conta alterada em outra aba. Tente novamente.');localStorage.setItem(storeKey,JSON.stringify(next));authEnter({key:newKey,record:next,storeKey,payload})}
async function bioSaveRecord(changes){await authQueue.catch(()=>{});const session=authSession;if(!session)throw Error('Entre na conta.');if(JSON.parse(localStorage.getItem(session.storeKey)||'null').revision!==session.record.revision)throw Error('Conta alterada em outra aba. Entre novamente.');const next=JSON.parse(JSON.stringify(Object.assign({},session.record,changes,{revision:session.record.revision+1})));localStorage.setItem(session.storeKey,JSON.stringify(next));session.record=next}
async function bioSetupStart(event){event.preventDefault();if(authBusy||!authSession)return;const v=readForm(event.target);authBusy=true;try{const session=authSession;const bits=await authKeyBits(v.current,session.record.salt);try{await authOpenWithBits(session.record,bits)}catch(e){throw Error('Senha atual incorreta.')}bioSetup={bits,step:'create'}}catch(e){notify(e.message||'Não foi possível ativar.')}finally{authBusy=false;render()}}
async function bioSetupCreate(){if(!bioSetup||!authSession)return;const record=authSession.record,salt=crypto.getRandomValues(new Uint8Array(32));let cred;try{cred=await navigator.credentials.create({publicKey:{rp:{name:'Estoque 99'},user:{id:crypto.getRandomValues(new Uint8Array(16)),name:record.login,displayName:record.login},challenge:crypto.getRandomValues(new Uint8Array(32)),pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required',residentKey:'preferred'},timeout:60000,attestation:'none',extensions:{prf:{eval:{first:salt}}}}})}catch(e){notify(e&&e.name==='NotAllowedError'?'Ativação cancelada.':'Não foi possível ativar o Face ID / digital neste aparelho.');return}
 const r=cred.getClientExtensionResults?cred.getClientExtensionResults():{};if(!r.prf||r.prf.enabled===false){bioSetup=null;render();notify('Este aparelho ou navegador não oferece desbloqueio por Face ID / digital.');return}
 bioSetup.id=authB64(cred.rawId);bioSetup.salt=authB64(salt);const out=bioPrfOut(cred);if(out)await bioFinish(out);else{bioSetup.step='get';render()}}
async function bioSetupConfirm(){if(!bioSetup||!bioSetup.id)return;try{await bioFinish(await bioGet({id:bioSetup.id,salt:bioSetup.salt}))}catch(e){notify(e.message)}}
async function bioFinish(out){try{const record=authSession.record,key=await bioKey(out,record.login);await bioSaveRecord({bio:await bioWrap(key,bioSetup.bits,record.login,bioSetup.id,bioSetup.salt)});bioSetup=null;notify('Face ID / digital ativado neste aparelho.')}catch(e){notify(e.message||'Não foi possível ativar.')}render()}
async function bioDisable(){if(!authSession||!confirm('Desativar o Face ID / digital desta conta?'))return;try{await bioSaveRecord({bio:undefined});notify('Face ID / digital desativado.')}catch(e){notify(e.message||'Não foi possível desativar.')}render()}
function authBioPanelHTML(){if(!bioSupported())return '';const on=!!authSession.record.bio;let body;
 if(bioSetup&&bioSetup.step==='create')body='<p>Senha confirmada.</p><div class="toolbar"><button type="button" class="primary" onclick="bioSetupCreate()">Continuar com Face ID / digital</button><button type="button" onclick="bioSetup=null;render()">Cancelar</button></div>';
 else if(bioSetup&&bioSetup.step==='get')body='<p>Falta confirmar uma vez.</p><div class="toolbar"><button type="button" class="primary" onclick="bioSetupConfirm()">Confirmar com Face ID / digital</button><button type="button" onclick="bioSetup=null;render()">Cancelar</button></div>';
 else if(on)body='<p>Ativado neste aparelho. Use para entrar ou em “Esqueci a senha”.</p><button type="button" onclick="bioDisable()">Desativar</button>';
 else body=`<p>Entre ou recupere o acesso com a biometria do aparelho.</p><form onsubmit="bioSetupStart(event)"><div class="fields">${authPasswordField('current','Senha atual','current-password')}<button class="primary" ${authBusy?'disabled':''}>Ativar Face ID / digital</button></div></form>`;
 return `<div class="panel help" id="bio-panel"><h2>Face ID / digital</h2>${body}</div>`}
/* Código de recuperação: só segue depois de baixar o arquivo ou digitar os 4 últimos caracteres. */
function authRecoveryCurrentCode(){return authRecoveryShow?authRecoveryShow.code:authShownCode}
function authRecoverySaved(){const c=authRecoveryCurrentCode();if(!c)return false;if(authSavedCode===c)return true;const i=$('recovery-last4');return !!i&&authNormalizeCode(i.value).length===4&&authNormalizeCode(i.value)===authNormalizeCode(c).slice(-4)}
function authRecoveryCheck(){const b=$('recovery-enter');if(b)b.disabled=!authRecoverySaved()}
function authRecoveryLast4HTML(){const c=authRecoveryCurrentCode();return `<label class="recovery-check">Digite os 4 últimos caracteres do código<input id="recovery-last4" maxlength="4" autocomplete="off" autocapitalize="characters" spellcheck="false" inputmode="text" oninput="authRecoveryCheck()"></label>`}
bioCheck().then(ok=>{if(!ok)return;if(authSession){if(page==='account')render()}else{const f=$('auth-form');if(f&&!authBusy&&!Array.from(f.querySelectorAll('input')).some(i=>i.value&&i.name!=='login'))renderAuth()}});

function authCopyText(text){try{navigator.clipboard.writeText(text).then(()=>notify('Código copiado.'),()=>notify('Não consegui copiar. Selecione o código e copie manualmente.'))}catch(e){notify('Não consegui copiar. Selecione o código e copie manualmente.')}}
