function authRecoveryFileText(login,code){return 'Estoque 99 · Código de recuperação\nLogin: '+login+'\nCódigo: '+authFormatCode(code)+'\n\nGuarde em lugar seguro. Quem tiver este código e uma cópia da conta consegue abrir os cadastros. Trocar a senha cria um novo código.\n'}
