function receiptSummary(n){const items=n.items||[];return {total:items.length,counted:items.filter(i=>i.received!==undefined&&i.received!=='').length,different:items.filter(i=>i.received!==undefined&&i.received!==''&&Math.abs(Number(i.received)-Number(i.quantity))>0.000001).length}}
function receiptInput(index,value){const item=nfImportDraft&&nfImportDraft.items[index];if(!item)return;if(value!==''&&(!/^\d+(\.\d{1,4})?$/.test(value)||!Number.isFinite(Number(value))||Number(value)>1e9)){notify('Informe quantidade positiva ou zero, com até 4 casas decimais.');return false}item.received=value;item.checkedAt=new Date().toISOString();const s=receiptSummary(nfImportDraft);if($('receipt-summary'))$('receipt-summary').textContent=s.counted+'/'+s.total+' itens contados · '+s.different+' divergências';return true}
function receiptScan(){const input=$('receipt-code'),code=input.value.trim(),items=nfImportDraft&&nfImportDraft.items||[],matches=items.map((item,index)=>({item,index})).filter(x=>x.item.code===code||(x.item.ean&&x.item.ean!=='SEM GTIN'&&x.item.ean===code));if(!code)return;if(matches.length!==1){notify(matches.length?'Código repetido no XML. Informe a quantidade na linha correta.':'Produto não encontrado nesta NF. Importe o XML correto.');return}const amount=Number($('receipt-step').value);if(!Number.isFinite(amount)||amount<=0||amount>1e9){notify('Informe uma quantidade válida por leitura.');return}const x=matches[0],next=(Number(x.item.received||0)+amount).toFixed(4);if(receiptInput(x.index,next)!==true)return;nfRenderImportDetails();$('receipt-step').value=String(amount);$('receipt-code').focus();notify(x.item.description+': '+next.replace('.',',')+' '+x.item.unit+' conferidos. Salve a NF.');}
function receiptMarkup(){if(!nfImportDraft||!nfImportDraft.items)return '';const s=receiptSummary(nfImportDraft);return `<section class="receipt-box"><h3>Conferência física</h3><p class="small">Importe o XML e bipe o código do produto. Cada leitura com Enter soma a quantidade abaixo na unidade comercial da nota. Caixas podem conter várias unidades: ajuste a quantidade antes de bipar. Nada é marcado como concluído automaticamente.</p><div class="pair"><label>Código do produto<input id="receipt-code" autocomplete="off" onkeydown="if(event.key==='Enter'){event.preventDefault();receiptScan()}" placeholder="EAN ou código interno"></label><label>Quantidade por leitura<input id="receipt-step" type="number" min="0.0001" max="1000000000" step="0.0001" value="1"></label></div><div class="toolbar"><button type="button" onclick="receiptScan()">Registrar leitura</button><button type="button" onclick="startOfflineCamera('product')">Câmera do produto</button></div><p id="receipt-summary" role="status">${s.counted}/${s.total} itens contados · ${s.different} divergências</p>${nfImportDraft.items.map((i,index)=>`<div class="receipt-item"><div><b>${esc(i.description)}</b><div class="small">${esc(i.code)} · Esperado: ${esc(i.quantity)} ${esc(i.unit)}</div></div><label>Recebido (${esc(i.unit)})<input type="number" aria-label="Quantidade recebida de ${esc(i.description)}" min="0" max="1000000000" step="0.0001" value="${esc(i.received===undefined?'':i.received)}" placeholder="Não contado" onchange="if(receiptInput(${index},this.value)===false)this.value=nfImportDraft.items[${index}].received||'';"></label></div>`).join('')}<p class="small">Campo vazio = ainda não contado; zero = nenhum recebido. Clique em Salvar para guardar a conferência.</p></section>`}
const renderImportBeforeUpgrade=nfRenderImportDetails;
nfRenderImportDetails=function(){renderImportBeforeUpgrade();const box=$('nf-import-details');if(box&&nfImportDraft&&nfImportDraft.items)box.innerHTML=receiptMarkup()+box.innerHTML};
const validateExtrasBeforeUpgrade=nfValidateExtras;
nfValidateExtras=function(n){validateExtrasBeforeUpgrade(n);for(const i of n.items||[]){if(i.received!==undefined&&i.received!==''&&(typeof i.received!=='string'||!/^\d+(\.\d{1,4})?$/.test(i.received)||Number(i.received)>1e9))throw Error('Quantidade conferida inválida.');if(i.checkedAt!==undefined&&(typeof i.checkedAt!=='string'||i.checkedAt.length>40||!Number.isFinite(Date.parse(i.checkedAt))))throw Error('Data da conferência inválida.')}return true};
