function cameraMarkup(){return `<section class="camera-box"><div class="toolbar"><button type="button" onclick="startOfflineCamera('nf')">Ler DANFE pela câmera</button><button type="button" onclick="stopOfflineCamera()">Fechar câmera</button></div><p id="camera-status" class="small" role="status"><span class="e99-pc">Leitor integrado ao arquivo, sem internet. A câmera depende de permissão e suporte do navegador. O leitor USB continua disponível.</span><span class="e99-touch">Funciona sem internet. Permita o uso da câmera quando o aparelho pedir.</span></p><video id="offline-camera" muted playsinline hidden></video></section>`}
