function stopOfflineCamera(){cameraSequence++;const session=cameraSession;cameraSession=null;if(session){if(session.stream)session.stream.getTracks().forEach(t=>t.stop());try{session.reader.reset()}catch(e){}}const video=$('offline-camera');if(video){video.srcObject=null;video.hidden=true}const status=$('camera-status');if(status)status.textContent='Câmera fechada. Use o leitor USB ou abra a câmera novamente.'}
async function startOfflineCamera(target){stopOfflineCamera();const status=$('camera-status'),video=$('offline-camera');if(!status||!video||!authSession)return;if(typeof ZXing==='undefined'&&window.e99Need){status.textContent='Abrindo o leitor de código…';try{await window.e99Need('zxing')}catch(e){status.textContent=e.message;return}}if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||typeof ZXing==='undefined'){status.textContent='Câmera indisponível neste contexto. Use o leitor USB. No celular, a prévia de um anexo pode bloquear câmera e JavaScript.';return}const token=cameraSequence,editor=editing;const session={reader:new ZXing.BrowserMultiFormatReader(),stream:null};cameraSession=session;status.textContent='Aguardando permissão da câmera…';try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920}},audio:false});if(token!==cameraSequence||!modal.open||editor!==editing){stream.getTracks().forEach(t=>t.stop());return}session.stream=stream;video.hidden=false;status.textContent='Centralize o código de barras, mantenha a câmera firme e boa iluminação.';await session.reader.decodeFromStream(stream,video,(result)=>{if(!result||token!==cameraSequence||editor!==editing)return;const code=result.getText();stopOfflineCamera();if(target==='product'){const input=$('receipt-code');if(input){input.value=code;receiptScan()}}else{$('editor').elements.namedItem('accessKey').value=code;nfApplyScan()}status.textContent='Código lido. Revise o resultado e salve a NF.'});}catch(e){if(token===cameraSequence){stopOfflineCamera();status.textContent='Não foi possível abrir a câmera. Confira a permissão, se outra aplicação está usando a câmera e se o navegador permite este arquivo local.'}}}
