  if(box&&!nfCut&&nfShownQ&&q.indexOf(nfShownQ)===0&&box.querySelector('tbody')){let n=0;box.querySelectorAll('tbody tr[data-q]').forEach(function(tr){const hit=tr.getAttribute('data-q').indexOf(q)>=0;tr.hidden=!hit;if(hit)n++});let em=box.querySelector('.empty-q');if(!n&&!em){em=document.createElement('div');em.className='empty empty-q';em.textContent='Nenhuma nota encontrada nesta seleção.';box.appendChild(em)}else if(n&&em)em.remove();return}
