try{siteSoundEnabled=localStorage.getItem('lojasg.estoque99.sound')!=='off'}catch(e){}
function updateSoundControl(){const b=$('sound-control');if(b){b.innerHTML='<span class="sound-icon" aria-hidden="true">'+(window.e99Icon?e99Icon(siteSoundEnabled?'sound':'mute'):(siteSoundEnabled?'♪':'×'))+'</span><span class="sound-label">'+(siteSoundEnabled?'Som ligado':'Som desligado')+'</span>';b.setAttribute('aria-pressed',String(siteSoundEnabled));b.setAttribute('aria-label',siteSoundEnabled?'Desativar efeitos sonoros':'Ativar efeitos sonoros')}}
/* v93: no iPhone o Web Audio fica mudo com a chave de silêncio (sessão "ambient") e só destrava num toque que termina (touchend/click).
   Por isso: sessão "playback", retomar dentro do gesto e tocar 1 amostra muda no mesmo gesto (destrave clássico do iOS). */
function unlockSiteAudio(){if(!siteSoundEnabled)return null;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return null;try{if(navigator.audioSession&&navigator.audioSession.type!=='playback')navigator.audioSession.type='playback'}catch(e){}if(!siteAudio||siteAudio.state==='closed')siteAudio=new Audio();if(siteAudio.state!=='running'){siteAudio.resume().catch(()=>{});if(!siteAudio.__e99u){try{const b=siteAudio.createBuffer(1,1,22050),src=siteAudio.createBufferSource();src.buffer=b;src.connect(siteAudio.destination);src.start(0);siteAudio.__e99u=1}catch(e){}}}return siteAudio}catch(e){return null}}
function playSiteSound(kind='tap'){if(!siteSoundEnabled||document.hidden)return;const ctx=siteAudio;if(!ctx||ctx.state!=='running')return;try{const now=ctx.currentTime,notes=kind==='login'?[[392,0,.24],[587.33,.1,.3],[783.99,.22,.48]]:[[660,0,.045]];for(const [frequency,delay,duration] of notes){const oscillator=ctx.createOscillator(),gain=ctx.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(frequency,now+delay);gain.gain.setValueAtTime(0,now+delay);gain.gain.linearRampToValueAtTime(kind==='login' ? .045 : .025,now+delay+.008);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+duration);oscillator.connect(gain);gain.connect(ctx.destination);oscillator.start(now+delay);oscillator.stop(now+delay+duration+.02);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()}}}catch(e){}}
function toggleSiteSound(){siteSoundEnabled=!siteSoundEnabled;try{localStorage.setItem('lojasg.estoque99.sound',siteSoundEnabled?'on':'off')}catch(e){}updateSoundControl();if(siteSoundEnabled){const ctx=unlockSiteAudio();if(ctx){if(ctx.state==='running')playSiteSound();else ctx.resume().then(()=>playSiteSound()).catch(()=>{})}}else if(siteAudio&&siteAudio.state==='running')siteAudio.suspend().catch(()=>{})}
document.addEventListener('pointerdown',()=>unlockSiteAudio(),{passive:true});document.addEventListener('touchend',()=>unlockSiteAudio(),{passive:true,capture:true});document.addEventListener('click',()=>unlockSiteAudio(),{capture:true});
document.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')unlockSiteAudio()});
document.addEventListener('click',event=>{const target=event.target&&typeof event.target.closest==='function'?event.target.closest('button,a,summary,select,[role="button"]'):null;if(!target||target.disabled||target.id==='sound-control')return;const now=Date.now();if(now-lastSiteTap<70)return;lastSiteTap=now;unlockSiteAudio();playSiteSound()});
