function learnNormalize(v){
 v=v&&typeof v==='object'&&!Array.isArray(v)?v:{};
 const pick=(x,max,fn)=>{const out={};if(x&&typeof x==='object'&&!Array.isArray(x)){for(const k of Object.keys(x).slice(0,max*2)){if(Object.keys(out).length>=max)break;if(typeof k!=='string'||!k||k.length>200)continue;const y=fn(x[k]);if(y!==undefined)out[k]=y}}return out};
 const count=n=>Number.isSafeInteger(n)&&n>=0&&n<1e9?n:0;
 const str=(s,n)=>typeof s==='string'?s.slice(0,n):'';
 const pr=v.prefs&&typeof v.prefs==='object'?v.prefs:{};
 return {
  on:v.on!==false,
  pages:pick(v.pages,LEARN_LIMIT.pages,n=>Number.isSafeInteger(n)&&n>0?n:undefined),
  titles:pick(v.titles,LEARN_LIMIT.titles,x=>x&&typeof x.t==='string'&&Number.isSafeInteger(x.n)&&x.n>0?{t:str(x.t,120),n:x.n}:undefined),
  questions:pick(v.questions,LEARN_LIMIT.questions,x=>x&&typeof x.t==='string'&&Number.isSafeInteger(x.n)&&x.n>0?{t:str(x.t,160),n:x.n,up:count(x.up),down:count(x.down)}:undefined),
  owners:pick(v.owners,LEARN_LIMIT.owners,x=>x&&typeof x==='object'&&!Array.isArray(x)?pick(x,10,n=>Number.isSafeInteger(n)&&n>0?n:undefined):undefined),
  approved:Array.isArray(v.approved)?v.approved.filter(x=>x&&typeof x.q==='string'&&typeof x.a==='string').slice(-LEARN_LIMIT.approved).map(x=>({q:str(x.q,300),a:str(x.a,800),at:str(x.at,40)})):[],
  improvements:Array.isArray(v.improvements)?v.improvements.filter(x=>x&&typeof x.text==='string').slice(0,LEARN_LIMIT.improvements).map(x=>({id:str(x.id,40)||('m'+Date.now().toString(36)+Math.random().toString(36).slice(2,6)),key:str(x.key,120),text:str(x.text,400),kind:x.kind==='manual'?'manual':'auto',at:str(x.at,40),done:x.done===true})):[],
  dismissed:pick(v.dismissed,LEARN_LIMIT.dismissed,x=>x===true?true:undefined),
  prefs:{startPage:typeof pr.startPage==='string'&&pr.startPage.length<=40?pr.startPage:''}
 };
}
function learnCfg(){const p=authSession&&authSession.payload;if(!p)return learnNormalize({});if(!p.learn)p.learn=learnNormalize({});return p.learn}
let learnTimer=null;
function learnSchedule(){if(!authSession)return;clearTimeout(learnTimer);learnTimer=setTimeout(learnFlush,1200)}
async function learnFlush(){learnTimer=null;if(!authSession)return;try{await authPersist(JSON.stringify(state))}catch(e){}}
function learnPage(p){if(!authSession)return;const c=learnCfg();if(!c.on||!labels[p])return;c.pages[p]=(c.pages[p]||0)+1;learnSchedule()}
function learnStartPage(){const s=learnCfg().prefs.startPage;return s&&s!=='admin'&&s!=='account'&&labels[s]?s:'home'}
function learnTitle(title){const c=learnCfg();if(!c.on)return;const t=String(title).trim().slice(0,120),key=normalText(t).slice(0,120);if(key.length<3)return;const row=c.titles[key];if(!row&&Object.keys(c.titles).length>=LEARN_LIMIT.titles)return;c.titles[key]={t:row?row.t:t,n:(row?row.n:0)+1}}
function learnOwner(corr,ownerId){const c=learnCfg();if(!c.on||!corr||!ownerId)return;if(!c.owners[corr]&&Object.keys(c.owners).length>=LEARN_LIMIT.owners)return;const row=c.owners[corr]||{};row[ownerId]=(row[ownerId]||0)+1;c.owners[corr]=row}
function learnDecorate(kind){
 if(kind!=='task'||!authSession)return;const f=$('editor'),ti=f.elements.title;if(!ti)return;
 ti.setAttribute('list','learn-titles');let dl=document.getElementById('learn-titles');if(!dl){dl=document.createElement('datalist');dl.id='learn-titles';document.body.appendChild(dl)}
 const c=learnCfg();dl.innerHTML=Object.keys(c.titles).map(k=>c.titles[k]).sort((a,b)=>b.n-a.n).slice(0,80).map(r=>'<option value="'+esc(r.t)+'"></option>').join('');
 let hint=document.getElementById('learn-hint');if(!hint){hint=document.createElement('p');hint.id='learn-hint';hint.className='small';hint.setAttribute('role','status')}
 $('fields').appendChild(hint);learnHintFor(f.elements.corridor?f.elements.corridor.value:'');
}
function learnHintFor(corr){const hint=document.getElementById('learn-hint');if(!hint)return;const row=corr&&learnCfg().owners[corr];if(!row){hint.textContent='';return}const top=Object.keys(row).sort((a,b)=>row[b]-row[a])[0];hint.textContent='Pelo seu histórico, este corredor costuma ser de '+owner(top)+'. Ajuste o responsável se precisar.'}
{const __go=go;go=function(p){learnPage(p);return __go.apply(this,arguments)}}
{const __oe=openEditor;openEditor=function(kind,id){const r=__oe.apply(this,arguments);learnDecorate(kind);return r}}


$('editor').addEventListener('change',ev=>{if(ev.target&&ev.target.name==='corridor')learnHintFor(ev.target.value)});
$('editor').addEventListener('submit',ev=>{
 if(!authSession||!editing||editing.kind!=='task'||editing.id)return;const f=ev.target,title=f.elements.title?f.elements.title.value.trim():'',corr=f.elements.corridor?f.elements.corridor.value:'',own=f.elements.owner?f.elements.owner.value:'';
 if(!title)return;
 setTimeout(()=>{if(!authSession||modal.open)return;learnTitle(title);if(corr&&own)learnOwner(corr,own);learnSchedule()},250);
});

state.alertSettings=normalizeAlertSettings(state.alertSettings);state.alertSnoozes=normalizeSnoozes(state.alertSnoozes);icons.alerts='⏱';labels.alerts='Alertas';icons.plans='▣';labels.plans='Plano de ação';
